void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float ix = texelFetch(iChannel1, ivec2(0,0), 0 ).x;
    int mono = int(texelFetch(iChannel1, ivec2(3,0), 0 ).x);
    int aa = 1-int(texelFetch(iChannel1, ivec2(5,0), 0 ).x);
    vec2 ppos = texelFetch(iChannel1, ivec2(10,0), 0 ).xy;
    fragColor*=0.;

    //ppos = vec2(sin(iTime*0.4)*20., cos(iTime*0.33)*20.);

    float maxz = 0.85;
    float layers = max(4., 6. - floor(iResolution.x / 900.));

    for (float l=0.; l<layers; l++) {
        float mx= mod(l*(maxz/layers)+iTime*0.066,maxz);
        vec2 mid = iResolution.xy / 2.;
        float mmul = 1.05-mx;
        vec2 FC = mid - (mid*mmul-fragCoord*mmul) + ppos;

        vec4 val = vec4(0.);
        int am=0, ap=aa, j=0;
        for (int j = -am; j <= ap; j++)
            for (int i = -am; i <= ap; i++)
            if ((int(l) % 2)==0)
                val += texelFetch(iChannel0, ivec2(int(FC.x)+i,int(FC.y)+j), 0 );
            else
                val += texelFetch(iChannel2, ivec2(int(FC.x)+i,int(FC.y)+j), 0 );


        float n=float((am+ap+1));
        if (am+ap > 0) val /= n*n-2.;

        if (aa == 0) val/=0.6;

        //float cm = 0. + max(0.,mod(iTime+l*1.0, 5.)-4.5);
        //if (cm>0.) cm = sin((cm / 0.5)*3.14) * 2.;

        //val *=vec4(1.,cm+1.,cm+1.,1.);

        //val[int(l)]=0.;
        fragColor += val * (sin(0.02+((1.0,mx/maxz))*(3.14))) * 1.;
    }

}

int cell( in ivec2 p )
{
    ivec2 r = ivec2(textureSize(iChannel0, 0));
    p = (p+r) % r;
    float val = texelFetch(iChannel0, p, 0 ).w;
    return ( val == liveval ) ? 1 : 0;
}
vec4 cellval( in ivec2 p )
{
    ivec2 r = ivec2(textureSize(iChannel0, 0));
    p = (p+r) % r;
    return texelFetch(iChannel0, p, 0 );
}

float randpix(vec2 fragCoord) {
    float rn = hash1(iTime+fragCoord.x*13.0+hash1(fragCoord.y*71.1));
    return clamp(step(1.01-density/100., rn), 0., 1.) * (liveval);
}

float restart(vec2 fragCoord, int method, bool preserve) {
    if (method == 0)
        return randpix(fragCoord);

    vec2 mid = iResolution.xy / 2.; 
    float w=100., h=100., radius=452., rradius=25.;
    if (iResolution.y < 1000.) radius=182.;
    float xrad=569.,yrad=453.;
    float thick=2., wl=w-thick, hl=h-thick;

    if (method == 1) {
        if (length(fragCoord-mid)< radius && length(fragCoord-mid) > (radius-thick))
            return liveval;
    }
    if (method == 2) {
        if (((fragCoord.x > mid.x - w && fragCoord.x < mid.x - wl) || (fragCoord.x > mid.x + wl && fragCoord.x < mid.x + w))
            && fragCoord.y > mid.y - h && fragCoord.y < mid.y + h)
            return liveval;
        if (((fragCoord.y > mid.y - h && fragCoord.y < mid.y - hl) || (fragCoord.y > mid.y + hl && fragCoord.y < mid.y + h))
            && fragCoord.x > mid.x - w && fragCoord.x < mid.x + w)
            return liveval;
    }
    if (method == 3) {
        if (length(vec2((fragCoord.x-mid.x)*0.793,(fragCoord.y-mid.y)*1.0))< radius)
            return liveval;
    }
    if (method == 4) {
        float xmul=1.; if (iResolution.y < 1000.) xmul=1.75;
        if (fragCoord.x > mid.x - rradius*xmul && fragCoord.x < mid.x + rradius*xmul+1. && fragCoord.y > mid.y - rradius && fragCoord.y < mid.y + rradius +1.)
            return randpix(fragCoord);
    }
    return preserve? -1. : 0.;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float ix = 0.;
    float xres = texelFetch(iChannel2, ivec2(0,1), 0 ).x;
    int speed = 4;//int(texelFetch(iChannel2, ivec2(2,0), 0 ).x);
    int mono = int(texelFetch(iChannel2, ivec2(3,0), 0 ).x);
    int rows = 2+ int(texelFetch(iChannel2, ivec2(4,0), 0 ).x);
    int iix = int(texelFetch(iChannel2, ivec2(1,0), 0 ).x);
    int method = int(texelFetch(iChannel2, ivec2(11,0), 0 ).x);
    int gen = 1 - int(texelFetch(iChannel2, ivec2(12,0), 0 ).x);

    setRules(iix);

    ivec2 px = ivec2( fragCoord );
    vec4 curr = cellval(px);
    float ev = curr.w;

    if( iFrame==0 || readKey(KEY_SPACE) || readKey(KEY_ENTER) || readKey(KEY_Z) || readKey(KEY_X) || int(xres) != int(iResolution.x) ) {
        fragColor = vec4( 0.0, 0.0, 0.0, restart(fragCoord, setmethod, false));
        return;
    }

    if( readKey(KEY_0) || readKey(KEY_1) || readKey(KEY_2) || readKey(KEY_3) || readKey(KEY_4) || readKey(KEY_5) || readKey(KEY_6) || readKey(KEY_7) || readKey(KEY_8) || readKey(KEY_9) ) {
        fragColor = vec4( 0.0, 0.0, 0.0, restart(fragCoord, setmethod, false));
        return;
    }

    if( readKey(KEY_Q) || readKey(KEY_W) || readKey(KEY_E) || readKey(KEY_R) || readKey(KEY_T) ) {
        fragColor = vec4( 0.0, 0.0, 0.0, restart(fragCoord, method, false));
        return;
    }

    if (iFrame % (speed+1) > 0) {
        fragColor = curr;
        return;
    }

    int k=0;

    int O=0, E=1+iFrame%nhp1, T=nhp2;
   // O=0, E=1+iFrame%40, T=2;

    if (nh == 0) {
        // ..X..
        // .X.X.
        // X.*.X
        // .X.X.
        // ..X..
        k =   cell(px+ivec2(O,-T)) + cell(px+ivec2(-E,-E)) + cell(px+ivec2(E,-E))
            + cell(px+ivec2(-T, O))                        + cell(px+ivec2(T, O))
            + cell(px+ivec2(-E, E)) + cell(px+ivec2(E, E)) + cell(px+ivec2(O, T));
    } else if (nh == 4 || nh==5 || nh == 6) {
        // .XXX. 4
        // XXXXX
        // XX*XX
        // XXXXX
        // .XXX.
        k =   cell(px+ivec2(-E, T)) + cell(px+ivec2(O, T)) + cell(px+ivec2(E, T))
            + cell(px+ivec2(-E, -T)) + cell(px+ivec2(O, -T)) + cell(px+ivec2(E, -T))
            + cell(px+ivec2(-T, -E)) + cell(px+ivec2(-T, O))
            + cell(px+ivec2(-T, E))
            + cell(px+ivec2(T, -E)) + cell(px+ivec2(T, O))
            + cell(px+ivec2(T, E));
        // XXXXX 6
        // X...X
        // X.*.X
        // X...X
        // XXXXX
        if (nh > 4) k += cell(px+ivec2(T, T)) + cell(px+ivec2(-T, -T)) + cell(px+ivec2(-T, T)) + cell(px+ivec2(T, -T));
        // XXXXX 5
        // XXXXX
        // XX*XX
        // XXXXX
        // XXXXX
        if (nh < 6)
            k += cell(px+ivec2(O,-E))
            + cell(px+ivec2(-E, O)) + cell(px+ivec2(E, O))
            + cell(px+ivec2(O, E))  + cell(px+ivec2(-E,-E)) + cell(px+ivec2(E,-E))
            + cell(px+ivec2(-E, E)) + cell(px+ivec2(E, E));


    } else if (nh == 7) {
        // XX.XX
        // X...X
        // ..*..
        // X...X
        // XX.XX
        k =   cell(px+ivec2(-T, -T)) + cell(px+ivec2(-E, -T)) + cell(px+ivec2(E, -T)) + cell(px+ivec2(T, -T))
            + cell(px+ivec2(-T, T)) + cell(px+ivec2(-E, T)) + cell(px+ivec2(E, T)) + cell(px+ivec2(T, T))
            + cell(px+ivec2(-T, -E)) + cell(px+ivec2(-T, E)) + cell(px+ivec2(T, E)) + cell(px+ivec2(T, -E));

    }
    else if (nh == 10) {
        // XXXXX
        // ..X..
        // ..*..
        // ..X..
        // XXXXX    
        k =   cell(px+ivec2(O,-E)) + cell(px+ivec2(O,E)) +
            + cell(px+ivec2(-T, -T)) + cell(px+ivec2(-E, -T)) + cell(px+ivec2(O, -T)) + cell(px+ivec2(E, -T)) + cell(px+ivec2(T, -T))
            + cell(px+ivec2(-T, T)) + cell(px+ivec2(-E, T)) + cell(px+ivec2(O, T)) + cell(px+ivec2(E, T)) + cell(px+ivec2(T, T));
    } else {
        // XXX
        // X*X
        // XXX
        k =   cell(px+ivec2(-E,-E)) + cell(px+ivec2(O,-E)) + cell(px+ivec2(E,-E))
            + cell(px+ivec2(-E, O))                        + cell(px+ivec2(E, O))
            + cell(px+ivec2(-E, E)) + cell(px+ivec2(O, E)) + cell(px+ivec2(E, E));
    }

    float ff = 0.;
    if (ev > 0.5) {
        if (decimate > 0.) ff = ev-decimate;
        if ((stayset & (1<<(k-1))) > 0 ) { ff = float(k); if (clampstay && ff > liveval) ff = liveval; }
    }
    else {
        ff = (bornset & (1<<(k-1))) > 0 ? liveval : 0.;
    }

    if (mono == 0) {
        if (ff >= 1.0) {
            int st = int(ff);

            float mulbase = float(k);
            if (colch == 1) mulbase = ff;
            else if (colch == 2) mulbase = 1.;
            else if (colch == 3) mulbase = float(k^st);

            if ((st & ra) > 0) curr.x += cstep*mulbase*rp;
            if ((st & ga) > 0) curr.y += cstep*mulbase*gp;
            if ((st & ba) > 0) curr.z += cstep*mulbase*bp;

            if (staypatt == 5 || staypatt == 6) curr.z=curr.y=curr.x;	

        } else {
            float stayt = cstep * stayval;

            if (staypatt == 0 || staypatt > 5) {
                curr.x -= cstep*rm;
                curr.y -= cstep*gm;
                curr.z -= cstep*bm;
            }
            else if (staypatt == 1) {
                if(curr.x > cstep) {
                    curr.x -= cstep*rm;
                    curr.y -= cstep*gm;
                    curr.z -= cstep*bm;
                }
            }
            else if (staypatt == 2) {
                if(curr.y > cstep) {
                    curr.x -= cstep*rm;
                    curr.y -= cstep*gm;
                    curr.z -= cstep*bm;
                }
            }
            else if (staypatt == 3) {
                if(curr.z > cstep) {
                    curr.x -= cstep*rm;
                    curr.y -= cstep*gm;
                    curr.z -= cstep*bm;
                }
            }
            else if (staypatt == 4) {
                if(curr.z > cstep) {
                    curr.x -= cstep*rm;
                    curr.y -= cstep*gm;
                }
                if(curr.x > cstep) curr.z -= cstep*bm;
            }
            else if (staypatt == 5) {
                curr.x -= cstep*rm;
                curr.z=curr.y=curr.x;
            }
        }
    }

	fragColor = vec4( clamp(curr.xyz,0.,1.), ff );
}

